+
+/// Independent elapsed work attribution for lifetimes crossing nested spans.
+/// Not exclusive time: do not sum it with the tree's stage durations.
+pub(crate) struct TimedWork {
+    counter: Work,
+    started: Option<(u64, Instant)>,
+    _thread: PhantomData<Rc<()>>,
+}
+impl TimedWork {
+    pub(crate) fn new(counter: Work) -> Self {
+        let started = ACTIVE.with(|active| active.borrow().as_ref()
+            .map(|state| (state.sample.sequence, Instant::now())));
+        Self { counter, started, _thread: PhantomData }
+    }
+}
+impl Drop for TimedWork {
+    fn drop(&mut self) {
+        if let Some((sequence, start)) = self.started.take() {
+            let nanos = start.elapsed().as_nanos().min(u64::MAX as u128) as u64;
+            ACTIVE.with(|active| {
+                if let Some(state) = active.borrow_mut().as_mut() {
+                    if state.sample.sequence == sequence {
+                        state.sample.work[self.counter as usize] += nanos;
+                    }
+                }
+            });
+        }
+    }
 }

 pub(crate) struct Probe(Option<(SpanToken, Instant)>);

